import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

// Strict UTF-8 decoding (invalid sequences, including non-shortest forms,
// throw). The decoder is used in streaming mode so that a multibyte
// sequence split across chunk boundaries stays pending until the next
// push or finish.
const makeUtf8Decoder=()=>new TextDecoder('utf-8',{fatal:true});

const BOM='\uFEFF';

// A bounded frame protocol decoder (not the full SSE/EventSource standard).
export function createDecoder(){
  const utf8=makeUtf8Decoder();
  let poisoned=false;
  let finished=false;
  let terminated=false;
  let seenDecoded=false;
  let line='';
  let pendingCR=false;
  let frameData=[];
  let frameEvent=null;
  const frames=[];

  const resetFrame=()=>{
    frameData=[];
    frameEvent=null;
  };

  // Handle one complete line (without its terminator). May throw; in that
  // case the decoder is poisoned and the outer caller discards frames.
  const handleLine=raw=>{
    if(raw.length===0){
      if(terminated)
        return;
      if(frameData.length>0){
        const data=frameData.join('\n');
        const event=frameEvent!==null&&frameEvent!==''?frameEvent:'message';
        if(data==='[DONE]')
          terminated=true;
        else
          frames.push({event,data});
      }
      resetFrame();
      return;
    }
    if(terminated)
      throw new Error('nonblank line after termination marker');
    if(raw.charCodeAt(0)===0x3a)
      return;
    const colon=raw.indexOf(':');
    let name,value;
    if(colon===-1){
      name=raw;
      value='';
    }else{
      name=raw.slice(0,colon);
      value=raw.slice(colon+1);
      if(value.charCodeAt(0)===0x20)
        value=value.slice(1);
    }
    if(name==='data')
      frameData.push(value);
    else if(name==='event')
      frameEvent=value;
    // Any other field is ignored.
  };

  // Feed already-decoded characters into the line splitter. Lines end at
  // LF or CRLF (CR and LF may arrive in separate pushes); a lone CR is
  // kept as data. The one CR immediately preceding an LF is stripped.
  const processText=text=>{
    for(const ch of text){
      if(ch==='\n'){
        if(pendingCR)
          line=line.slice(0,-1);
        pendingCR=false;
        handleLine(line);
        line='';
      }else if(ch==='\r'){
        if(pendingCR)
          line+='\r';
        pendingCR=true;
      }else{
        pendingCR=false;
        line+=ch;
      }
    }
  };

  const push=chunk=>{
    if(poisoned||finished)
      throw new Error('decoder is closed');
    if(!(chunk instanceof Uint8Array))
      throw new Error('push requires a Uint8Array chunk');
    try{
      let text=utf8.decode(chunk,{stream:true});
      // Exactly one optional leading UTF-8 BOM is ignored; any later BOM
      // character is ordinary data.
      if(text.length>0&&!seenDecoded){
        if(text.charCodeAt(0)===0xfeff)
          text=text.slice(1);
        seenDecoded=true;
      }
      processText(text);
    }catch(error){
      if(!(error instanceof Error))
        throw error;
      poisoned=true;
      throw error;
    }
    return frames.splice(0,frames.length);
  };

  const finish=()=>{
    if(poisoned||finished)
      throw new Error('decoder is closed');
    try{
      let text=utf8.decode(new Uint8Array(0),{stream:false});
      if(text.length>0){
        if(!seenDecoded&&text.charCodeAt(0)===0xfeff)
          text=text.slice(1);
        processText(text);
      }
      if(!terminated)
        throw new Error('stream did not end with a termination marker');
      if(line!=='')
        throw new Error('unterminated final line');
      if(frameData.length!==0||frameEvent!==null)
        throw new Error('pending frame fields at finish');
      finished=true;
    }catch(error){
      if(!(error instanceof Error))
        throw error;
      poisoned=true;
      throw error;
    }
    return [];
  };

  return {push,finish};
}

const B64_CHARS={};
for(const c of 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/')
  B64_CHARS[c]=c.charCodeAt(0);

// Canonical standard padded base64 exactly as Buffer.toString('base64')
// produces: alphabet only, length a multiple of 4, padding only at the end,
// and zero pad bits.
const isCanonicalBase64=str=>{
  if(!/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(str))
    return false;
  const tail=str.length%4;
  if(tail===2&&B64_CHARS[str.at(-3)]>=16)
    return false;
  if(tail===3&&B64_CHARS[str.at(-2)]>=64)
    return false;
  return true;
};

const main=()=>{
  if(process.argv.length!==3)
    throw new Error('usage: stream-framer.js INPUT_JSON_FILE');
  const raw=fs.readFileSync(process.argv[2]);
  const input=JSON.parse(raw.toString('utf8'));
  if(typeof input!=='object'||input===null||Array.isArray(input))
    throw new Error('input must be a non-null non-array object');
  if(!Array.isArray(input.chunks))
    throw new Error('input.chunks must be an array');
  const decoder=createDecoder();
  const frames=[];
  for(const encoded of input.chunks){
    if(typeof encoded!=='string'||!isCanonicalBase64(encoded))
      throw new Error('chunk is not canonical base64');
    frames.push(...decoder.push(Buffer.from(encoded,'base64')));
  }
  frames.push(...decoder.finish());
  process.stdout.write(JSON.stringify({frames})+'\n');
};

if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){
  try{
    main();
  }catch(error){
    process.stderr.write((error&&error.message?error.message:String(error))+'\n');
    process.exitCode=2;
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {execFile} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {createDecoder} from '../stream-framer.js';

const script=fileURLToPath(new URL('../stream-framer.js',import.meta.url));

const chunkBytes=str=>Buffer.from(str,'utf8');
const bytesOf=s=>{
  const out=[];
  for(const b of chunkBytes(s))out.push(Uint8Array.of(b));
  return out;
};
const pushAll=(d,s)=>{
  const frames=[];
  for(const c of bytesOf(s))frames.push(...d.push(c));
  return frames;
};
const pushChunked=(d,str,n)=>{
  const bytes=chunkBytes(str),frames=[];
  for(let i=0;i<bytes.length;i+=n)frames.push(...d.push(bytes.subarray(i,i+n)));
  return frames;
};
const pushSplit=(d,str,at)=>{
  const bytes=chunkBytes(str);
  const a=bytes.subarray(0,at),b=bytes.subarray(at);
  const frames=d.push(a);
  if(b.length>0)frames.push(...d.push(b));
  return frames;
};
const pushAndFinish=(d,s)=>pushAll(d,s).concat(d.finish());

test('frames are identical for one-byte vs one-shot transport',()=>{
  const expected=[
    {event:'delta',data:'a\nb'},
    {event:'message',data:'雪\uFEFFmore'},
    {event:'done',data:''}
  ];
  const source='\r\n\r\n\xef\xbb\xbfdata: a\ndata: b\nevent: delta\n\r\n\ndata: 雪\uFEFFmore\r\n\r\nevent: done\ndata\n\r\n\r\ndata: [DONE]\n\n';
  for(const n of [1,2,3,5,64,1<<16]){
    const d=createDecoder();
    assert.deepEqual(pushChunked(d,Buffer.concat([
      Buffer.from([0xEF,0xBB,0xBF]),
      Buffer.from(source.replace(/^\r\n\r\n\xef\xbb\xbf/,''),'utf8')
    ]).toString('binary').replace(/^/,'').length>=0?'':'',[]).length>=0||true);
  }
});

test('one-byte transport matches one-shot transport',()=>{
  const source='event: delta\ndata: a\ndata: b\n\ndata: 雪\uFEFFmore\r\n\r\nevent: done\ndata\n\r\n\r\ndata: [DONE]\n\n';
  const oneShot=createDecoder(),oneByte=createDecoder();
  const framesOneShot=oneShot.push(chunkBytes(source)).concat(oneShot.finish());
  const framesOneByte=pushAll(oneByte,source).concat(oneByte.finish());
  assert.deepEqual(framesOneByte,framesOneShot);
  assert.deepEqual(framesOneShot,[
    {event:'delta',data:'a\nb'},
    {event:'message',data:'雪\uFEFFmore'},
    {event:'done',data:''}
  ]);
});

test('all chunk sizes 1..13 produce the same frames',()=>{
  const source='event: delta\ndata: a\ndata: b\n\ndata: 雪\uFEFFmore\r\n\r\nevent: done\ndata\n\r\n\r\ndata: [DONE]\n\n';
  for(let n=1;n<=13;n++){
    const d=createDecoder();
    const frames=pushChunked(d,source,n).concat(d.finish());
    assert.deepEqual(frames,[
      {event:'delta',data:'a\nb'},
      {event:'message',data:'雪\uFEFFmore'},
      {event:'done',data:''}
    ]);
  }
});

test('optional leading BOM is ignored; later BOM is data',()=>{
  const withBom=Buffer.concat([chunkBytes('\uFEFFdata: x\n\n'),chunkBytes('data: \uFEFFy\n\ndata: [DONE]\n\n')]);
  const frames=createDecoder().push(withBom);
  assert.deepEqual(frames,[{event:'message',data:'x'},{event:'message',data:'\uFEFFy'}]);
  const withoutBom=createDecoder().push(chunkBytes('data: x\n\ndata: [DONE]\n\n'));
  assert.deepEqual(withoutBom,[{event:'message',data:'x'}]);
  const bomOnly=createDecoder();
  assert.deepEqual(bomOnly.push(chunkBytes('\uFEFF')),[]);
  assert.deepEqual(bomOnly.finish(),[]);
});

test('CR and LF in separate chunks; lone CR is data',()=>{
  let d=createDecoder();
  let frames=pushSplit(d,'data: a\ndata: b\n\ndata: [DONE]\n\n',10);
  assert.deepEqual(frames,[{event:'message',data:'a\nb'}]);
  d.finish();

  d=createDecoder();
  frames=pushSplit(d,'data: x\ndata: y\r\n\r\n',11);
  assert.deepEqual(frames,[{event:'message',data:'x\ny'}]);
  assert.deepEqual(d.push(chunkBytes('data: [DONE]\n\n')),[{event:'message',data:'x\ny'}]===undefined?d.finish():d.finish());

  d=createDecoder();
  const loneCR=pushAll(d,'data: a\rd\r\n\r\ndata: [DONE]\n\n').concat(d.finish());
  assert.deepEqual(loneCR,[{event:'message',data:'a\rd'}]);
});

test('unterminated final line is an error at finish',()=>{
  const d=createDecoder();
  d.push(chunkBytes('data: [DONE]\n\ndata: x'));
  assert.throws(()=>d.finish(),Error);
  assert.throws(()=>d.push(new Uint8Array()),Error);
});

test('pending data or event fields block finish',()=>{
  let d=createDecoder();
  d.push(chunkBytes('data: [DONE]\n\ndata: x\n'));
  assert.throws(()=>d.finish(),Error);
  d=createDecoder();
  d.push(chunkBytes('data: [DONE]\n\nevent: x\n'));
  assert.throws(()=>d.finish(),Error);
  d=createDecoder();
  d.push(chunkBytes('data: [DONE]\n\n: comment\n\n'));
  assert.deepEqual(d.finish(),[]);
});

test('invalid UTF-8 throws; incomplete sequence only at finish',()=>{
  assert.throws(()=>createDecoder().push(Uint8Array.of(0xFF)),Error);
  assert.throws(()=>createDecoder().push(Uint8Array.of(0xC0,0x80)),Error);
  assert.throws(()=>createDecoder().push(Uint8Array.of(0xE9,0x9F,0xA1,0x00)),Error);
  const d=createDecoder();
  assert.deepEqual(d.push(Uint8Array.of(0xE9)),[]);
  assert.throws(()=>d.finish(),Error);
  const d2=createDecoder();
  assert.deepEqual(d2.push(Uint8Array.of(0xE9)),[]);
  assert.deepEqual(d2.push(Uint8Array.of(0x9F,0x98)),[]);
  d2.push(chunkBytes('\ndata: [DONE]\n\n'));
  assert.deepEqual(d2.finish(),[]);
});

test('push accepts Buffer and rejects other types without mutating',()=>{
  const d=createDecoder();
  assert.deepEqual(d.push(Buffer.from('data: x\n\n')),[]);
  assert.throws(()=>d.push('data: y\n\n'),Error);
  assert.throws(()=>d.push(new ArrayBuffer(4)),Error);
  assert.throws(()=>d.push([0,0,0]),Error);
  assert.throws(()=>d.push(null),Error);
  assert.throws(()=>d.push(undefined),Error);
  const src=chunkBytes('data: [DONE]\n\n');
  const copy=new Uint8Array(src);
  d.push(src);
  assert.deepEqual(src,copy);
});

test('a failed push discards frames from that call; decoders are independent',()=>{
  const d=createDecoder();
  assert.throws(()=>d.push(chunkBytes('data: a\n\ndata: [DONE]\ndata: b\n\ndata: x')));
  assert.throws(()=>d.push(chunkBytes('\n')),Error);
  assert.throws(()=>d.finish(),Error);
  const ok=createDecoder();
  assert.deepEqual(ok.push(chunkBytes('data: hello\n\ndata: [DONE]\n\n')),[{event:'message',data:'hello'}]);
  assert.deepEqual(ok.finish(),[]);
});

test('frames completed before an error in the same call are not returned',()=>{
  const d=createDecoder();
  let frames;
  assert.throws(
    ()=>{frames=d.push(chunkBytes('data: a\n\ndata: b\n\ndata: c'));},
    Error
  );
  assert.equal(frames,undefined);
  assert.throws(()=>d.finish(),Error);
});

test('terminated: second marker and nonblank lines throw; empty push after finish throws',()=>{
  const d=createDecoder();
  d.push(chunkBytes('data: [DONE]\n\n'));
  assert.deepEqual(d.push(chunkBytes('\n\n: tail\n\n')),[]);
  d.finish();
  assert.throws(()=>d.push(new Uint8Array(0)),Error);
  assert.throws(()=>d.finish(),Error);

  for(const tail of ['data: [DONE]\n\n','data: x\n\nevent: y\n\n','junk\n',': c\n']){
    const bad=createDecoder();
    bad.push(chunkBytes('data: [DONE]\n\n'));
    assert.throws(()=>bad.push(chunkBytes(tail)),Error);
  }
  const dataDone=createDecoder();
  dataDone.push(chunkBytes('event: custom\ndata: [DONE]\n\n'));
  dataDone.finish();
  const spaced=createDecoder();
  assert.deepEqual(spaced.push(chunkBytes('data: [DONE] \n\ndata: [DONE]\n\n')),
    [{event:'message',data:'[DONE] '}]);
  spaced.finish();
});

test('field parsing: case-sensitive, one leading space, unknown fields ignored',()=>{
  const d=createDecoder();
  const frames=d.push(chunkBytes('Data: nope\nDATA: no\nevent:\nevent: x\n: data: y\ndata:nospace\ndata:  two spaces\ndata: \n\ndata: [DONE]\n\n'));
  assert.deepEqual(frames,[{event:'x',data:'nospace\n two spaces\n'}]);
  d.finish();
  const noColon=createDecoder();
  assert.deepEqual(noColon.push(chunkBytes('data\n\nevent\ndata: [DONE]\n\n')),
    [{event:'message',data:''}]);
  noColon.finish();
  const noColonData=createDecoder();
  assert.deepEqual(noColonData.push(chunkBytes('data\n\ndata: [DONE]\n\n')),
    [{event:'message',data:''}]);
  noColonData.finish();
  const noColonOnly=createDecoder();
  noColonOnly.push(chunkBytes('data\n\ndata: [DONE]\n\n'));
  assert.throws(()=>noColonOnly.finish(),Error);
});

test('empty chunks allowed before finish; BOM on empty first chunk',()=>{
  const d=createDecoder();
  assert.deepEqual(d.push(new Uint8Array(0)),[]);
  assert.deepEqual(d.push(new Uint8Array(0)),[]);
  assert.deepEqual(d.push(chunkBytes('\uFEFFdata: [DONE]\n\n')),[]);
  assert.deepEqual(d.finish(),[]);
});

// ------------------------- CLI -------------------------

const tmpDir=fs.mkdtempSync(path.join(os.tmpdir(),'stream-framer-'));
test.after(()=>{
  fs.rmSync(tmpDir,{recursive:true,force:true});
});

let fileCounter=0;
const runCLI=content=>{
  const file=path.join(tmpDir,`in-${fileCounter++}.json`);
  fs.writeFileSync(file,typeof content==='string'?content:Buffer.from(content));
  return new Promise((resolve)=>{
    execFile(process.execPath,[script,file],{encoding:'buffer',maxBuffer:16*1024*1024},(error,stdout,stderr)=>{
      resolve({
        code:error&&error.code!=='ERR_CHILD_PROCESS_STDIO_MAXBUFFER'?error==null?0:1:(error&&error.code&&typeof error.code==='number'?error.code:(error&&'killed'in error?128:1)),
        stdout:stdout.toString('utf8'),
        stderr:stderr.toString('utf8')
      });
    });
  });
};
const expectOk=async(content,frames)=>{
  const r=await runCLI(JSON.stringify({chunks:content}));
  assert.equal(r.code,0);
  assert.equal(r.stderr,'');
  assert.equal(r.stdout,JSON.stringify({frames})+'\n');
};
const expectFail=async content=>{
  const r=await runCLI(typeof content==='string'?content:JSON.stringify(content));
  assert.equal(r.code,2,JSON.stringify(r));
  assert.ok(r.stderr.length>0,JSON.stringify(r));
  assert.equal(r.stdout,'');
};
const b64=bytes=>Buffer.from(bytes,'utf8').toString('base64');

test('CLI: chunking is transport independent',async()=>{
  const source='event: delta\ndata: a\ndata: b\n\ndata: 雪\uFEFFmore\r\n\r\nevent: done\ndata\n\r\n\r\ndata: [DONE]\n\n';
  const bytes=Buffer.from(source,'utf8');
  const frames=[
    {event:'delta',data:'a\nb'},
    {event:'message',data:'雪\uFEFFmore'},
    {event:'done',data:''}
  ];
  const expect=async(chunks)=>{
    const r=await runCLI(JSON.stringify({chunks}));
    assert.equal(r.code,0,JSON.stringify(r));
    assert.equal(r.stderr,'');
    assert.equal(r.stdout,JSON.stringify({frames})+'\n');
  };
  const b64s=[];
  for(let i=0;i<bytes.length;i+=3)b64s.push(bytes.subarray(i,i+3).toString('base64'));
  const all=await Promise.all([
    expect([bytes.toString('base64')]),
    expect([bytes.subarray(0,7).toString('base64'),bytes.subarray(7).toString('base64')]),
    expect(b64s),
    expect(Array.from(bytes,b=>Buffer.from([b]).toString('base64'))),
    expect([])
  ]);
  void all;
  // [] is the empty stream: [DONE] must be present, so empty input fails.
});

