import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {execFile} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {createDecoder} from '../stream-framer.js';

const script=fileURLToPath(new URL('../stream-framer.js',import.meta.url));

const chunkBytes=str=>Buffer.from(str,'utf8');
const bytesOf=s=>{
  const out=[];
  for(const b of chunkBytes(s))out.push(Uint8Array.of(b));
  return out;
};
const pushAll=(d,s)=>{
  const frames=[];
  for(const c of bytesOf(s))frames.push(...d.push(c));
  return frames;
};
const pushChunked=(d,str,n)=>{
  const bytes=chunkBytes(str),frames=[];
  for(let i=0;i<bytes.length;i+=n)frames.push(...d.push(bytes.subarray(i,i+n)));
  return frames;
};
const pushSplit=(d,str,at)=>{
  const bytes=chunkBytes(str);
  const a=bytes.subarray(0,at),b=bytes.subarray(at);
  const frames=d.push(a);
  if(b.length>0)frames.push(...d.push(b));
  return frames;
};

const SOURCE='event: delta\ndata: a\ndata: b\n\ndata: 雪\uFEFFmore\r\n\r\nevent: done\ndata\n\r\n\r\ndata: [DONE]\n\n';
const EXPECTED=[
  {event:'delta',data:'a\nb'},
  {event:'message',data:'雪\uFEFFmore'},
  {event:'done',data:''}
];

test('one-byte transport matches one-shot transport',()=>{
  const oneShot=createDecoder();
  const framesOneShot=oneShot.push(chunkBytes(SOURCE)).concat(oneShot.finish());
  const framesOneByte=pushAll(createDecoder(),SOURCE).concat(createDecoder().finish()||[]);
  assert.deepEqual(framesOneShot,EXPECTED);
  assert.deepEqual(framesOneByte,EXPECTED);
});

test('all chunk sizes 1..13 produce the same frames',()=>{
  for(let n=1;n<=13;n++){
    const frames=pushChunked(createDecoder(),SOURCE,n).concat(createDecoder().finish()||[]);
    assert.deepEqual(frames,EXPECTED);
  }
});

test('optional leading BOM is ignored; later BOM is data',()=>{
  const withBom=Buffer.concat([chunkBytes('\uFEFFdata: x\n\n'),chunkBytes('data: \uFEFFy\n\ndata: [DONE]\n\n')]);
  const frames=createDecoder().push(withBom);
  assert.deepEqual(frames,[{event:'message',data:'x'},{event:'message',data:'\uFEFFy'}]);
  const withoutBom=createDecoder().push(chunkBytes('data: x\n\ndata: [DONE]\n\n'));
  assert.deepEqual(withoutBom,[{event:'message',data:'x'}]);
  const bomOnly=createDecoder();
  assert.deepEqual(bomOnly.push(chunkBytes('\uFEFF')),[]);
  assert.throws(()=>bomOnly.finish(),Error);
  const bomLate=createDecoder();
  bomLate.push(new Uint8Array(0));
  assert.deepEqual(bomLate.push(chunkBytes('\uFEFFdata: [DONE]\n\n')),[]);
  assert.deepEqual(bomLate.finish(),[]);
});

test('CR and LF in separate chunks; lone CR is data',()=>{
  let d=createDecoder();
  let frames=pushSplit(d,'data: a\ndata: b\n\ndata: [DONE]\n\n',10);
  assert.deepEqual(frames,[{event:'message',data:'a\nb'}]);
  assert.deepEqual(d.finish(),[]);

  // split so the first chunk ends at a CR and the next chunk starts at LF
  d=createDecoder();
  frames=pushSplit(d,'data: x\ndata: y\r\n\r\n',16);
  assert.deepEqual(frames,[{event:'message',data:'x\ny'}]);
  assert.deepEqual(d.push(chunkBytes('data: [DONE]\n\n')),[]);
  assert.deepEqual(d.finish(),[]);

  d=createDecoder();
  const loneCR=pushAll(d,'data: a\rd\r\n\r\ndata: [DONE]\n\n').concat(d.finish());
  assert.deepEqual(loneCR,[{event:'message',data:'a\rd'}]);
});

test('unterminated final line is an error at finish',()=>{
  const d=createDecoder();
  d.push(chunkBytes('data: [DONE]\n\ndata: x'));
  assert.throws(()=>d.finish(),Error);
  assert.throws(()=>d.push(new Uint8Array()),Error);
});

test('pending data or event fields block finish; comments and blanks are fine',()=>{
  let d=createDecoder();
  d.push(chunkBytes('data: [DONE]\n\ndata: x\n'));
  assert.throws(()=>d.finish(),Error);
  d=createDecoder();
  d.push(chunkBytes('data: [DONE]\n\nevent: x\n'));
  assert.throws(()=>d.finish(),Error);
  d=createDecoder();
  d.push(chunkBytes('data: [DONE]\n\n: comment\n\n'));
  assert.deepEqual(d.finish(),[]);
});

test('invalid UTF-8 throws; incomplete sequence only at finish',()=>{
  assert.throws(()=>createDecoder().push(Uint8Array.of(0xFF)),Error);
  assert.throws(()=>createDecoder().push(Uint8Array.of(0xC0,0x80)),Error);
  assert.throws(()=>createDecoder().push(Uint8Array.of(0xE9,0x9F,0xA1,0x00)),Error);
  const d=createDecoder();
  assert.deepEqual(d.push(Uint8Array.of(0xE9)),[]);
  assert.throws(()=>d.finish(),Error);
  const d2=createDecoder();
  assert.deepEqual(d2.push(Uint8Array.of(0xE9)),[]);
  assert.deepEqual(d2.push(Uint8Array.of(0x9F,0x98)),[]);
  assert.deepEqual(d2.push(chunkBytes('\ndata: [DONE]\n\n')),[]);
  assert.deepEqual(d2.finish(),[]);
});

test('push accepts Buffer and rejects other types without mutating',()=>{
  const d=createDecoder();
  assert.deepEqual(d.push(Buffer.from('data: x\n')),[]);
  for(const bad of ['data: y\n\n',new ArrayBuffer(4),[0,0,0],null,undefined])
    assert.throws(()=>d.push(bad),Error);
  const src=chunkBytes('data: [DONE]\n\n');
  const copy=new Uint8Array(src);
  d.push(src);
  assert.deepEqual(src,copy);
});

test('a failed push discards frames from that call; decoders are independent',()=>{
  const d=createDecoder();
  const bad=Buffer.concat([chunkBytes('data: a\n\ndata: [DONE]\n\ndata: b\n'),Uint8Array.of(0xFF)]);
  assert.throws(()=>d.push(bad),Error);
  assert.throws(()=>d.push(chunkBytes('\n')),Error);
  assert.throws(()=>d.finish(),Error);
  const ok=createDecoder();
  assert.deepEqual(ok.push(chunkBytes('data: hello\n\ndata: [DONE]\n\n')),[{event:'message',data:'hello'}]);
  assert.deepEqual(ok.finish(),[]);
});

test('frames completed before an error in the same call are not returned',()=>{
  const d=createDecoder();
  let frames;
  const bad=Buffer.concat([chunkBytes('data: a\n\ndata: b\n\n'),Uint8Array.of(0xFF)]);
  assert.throws(()=>{frames=d.push(bad);},Error);
  assert.equal(frames,undefined);
  assert.throws(()=>d.finish(),Error);
});

test('terminated: only blank lines allowed after the marker',()=>{
  const d=createDecoder();
  d.push(chunkBytes('data: [DONE]\n\n'));
  assert.deepEqual(d.push(chunkBytes('\n\n')),[]);
  assert.throws(()=>d.push(chunkBytes(': tail\n')),Error);
  assert.throws(()=>d.finish(),Error);

  const fresh=createDecoder();
  fresh.push(chunkBytes('data: [DONE]\n\n'));
  fresh.push(chunkBytes('\n\n'));
  fresh.finish();
  assert.throws(()=>fresh.push(new Uint8Array(0)),Error);
  assert.throws(()=>fresh.finish(),Error);

  for(const tail of ['data: [DONE]\n\n','data: x\n\nevent: y\n\n','junk\n',': c\n']){
    const bad=createDecoder();
    bad.push(chunkBytes('data: [DONE]\n\n'));
    assert.throws(()=>bad.push(chunkBytes(tail)),Error);
  }
  const customEvent=createDecoder();
  customEvent.push(chunkBytes('event: custom\ndata: [DONE]\n\n'));
  assert.deepEqual(customEvent.finish(),[]);
  const spaced=createDecoder();
  assert.deepEqual(spaced.push(chunkBytes('data: [DONE] \n\ndata: [DONE]\n\n')),
    [{event:'message',data:'[DONE] '}]);
  spaced.finish();
});

test('field parsing: case-sensitive, one leading space, unknown fields ignored',()=>{
  const d=createDecoder();
  const frames=d.push(chunkBytes('Data: nope\nDATA: no\nevent:\nevent: x\n: data: y\ndata:nospace\ndata:  two spaces\ndata: \n\ndata: [DONE]\n\n'));
  assert.deepEqual(frames,[{event:'x',data:'nospace\n two spaces\n'}]);
  d.finish();
  const noColon=createDecoder();
  assert.deepEqual(noColon.push(chunkBytes('data\n\nevent\ndata: [DONE]\n\n')),
    [{event:'message',data:''}]);
  noColon.finish();
  const noColonData=createDecoder();
  assert.deepEqual(noColonData.push(chunkBytes('data\n\ndata: [DONE]\n\n')),
    [{event:'message',data:''}]);
  noColonData.finish();
});

test('empty chunks allowed before finish',()=>{
  const d=createDecoder();
  assert.deepEqual(d.push(new Uint8Array(0)),[]);
  assert.deepEqual(d.push(new Uint8Array(0)),[]);
  assert.deepEqual(d.push(chunkBytes('\uFEFFdata: [DONE]\n\n')),[]);
  assert.deepEqual(d.finish(),[]);
});

