});

const runExec=()=>new Promise(resolve=>{
  const args=runExec.args;
  execFile(process.execPath,args,{encoding:'buffer',maxBuffer:16*1024*1024},(error,stdout,stderr)=>{
    resolve({
      code:error==null?0:(typeof error.code==='number'?error.code:1),
      stdout:stdout.toString('utf8'),
      stderr:stderr.toString('utf8')
    });
  });
});

let fileCounter=0;
const runCLI=content=>{
  const file=path.join(tmpDir,`in-${fileCounter++}.json`);
  fs.writeFileSync(file,typeof content==='string'?content:Buffer.from(content));
  runExec.args=[script,file];
  return runExec();
};
const b64=s=>Buffer.from(s,'utf8').toString('base64');

const expectOk=async(content,frames)=>{
  const r=await runCLI(JSON.stringify({chunks:content}));
  assert.equal(r.code,0,JSON.stringify(r));
  assert.equal(r.stderr,'');
  assert.equal(r.stdout,JSON.stringify({frames})+'\n');
};
