import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

// Strict UTF-8 decoding (invalid sequences, including non-shortest forms,
// throw). The decoder is used in streaming mode so that a multibyte
// sequence split across chunk boundaries stays pending until the next
// push or finish.
const makeUtf8Decoder=()=>new TextDecoder('utf-8',{fatal:true});

const BOM='\uFEFF';

// A bounded frame protocol decoder (not the full SSE/EventSource standard).
export function createDecoder(){
  const utf8=makeUtf8Decoder();
  let poisoned=false;
  let finished=false;
  let terminated=false;
  let seenDecoded=false;
  let line='';
  let pendingCR=false;
  let frameData=[];
  let frameEvent=null;
  const frames=[];

  const resetFrame=()=>{
    frameData=[];
    frameEvent=null;
  };

  // Handle one complete line (without its terminator). May throw; in that
  // case the decoder is poisoned and the outer caller discards frames.
  const handleLine=raw=>{
    if(raw.length===0){
      if(terminated)
        return;
      if(frameData.length>0){
        const data=frameData.join('\n');
        const event=frameEvent!==null&&frameEvent!==''?frameEvent:'message';
        if(data==='[DONE]')
          terminated=true;
        else
          frames.push({event,data});
      }
      resetFrame();
      return;
    }
    if(terminated)
      throw new Error('nonblank line after termination marker');
    if(raw.charCodeAt(0)===0x3a)
      return;
    const colon=raw.indexOf(':');
    let name,value;
    if(colon===-1){
      name=raw;
      value='';
    }else{
      name=raw.slice(0,colon);
      value=raw.slice(colon+1);
      if(value.charCodeAt(0)===0x20)
        value=value.slice(1);
    }
    if(name==='data')
      frameData.push(value);
    else if(name==='event')
      frameEvent=value;
    // Any other field is ignored.
  };

  // Feed already-decoded characters into the line splitter. Lines end at
  // LF or CRLF (CR and LF may arrive in separate pushes); a lone CR is
  // kept as data. The one CR immediately preceding an LF is stripped.
  const processText=text=>{
    for(const ch of text){
      if(ch==='\n'){
        if(pendingCR)
          line=line.slice(0,-1);
        pendingCR=false;
        handleLine(line);
        line='';
      }else if(ch==='\r'){
        if(pendingCR)
          line+='\r';
        pendingCR=true;
      }else{
        pendingCR=false;
        line+=ch;
      }
    }
  };

  const push=chunk=>{
    if(poisoned||finished)
      throw new Error('decoder is closed');
    if(!(chunk instanceof Uint8Array))
      throw new Error('push requires a Uint8Array chunk');
    try{
      let text=utf8.decode(chunk,{stream:true});
      // Exactly one optional leading UTF-8 BOM is ignored; any later BOM
      // character is ordinary data.
      if(text.length>0&&!seenDecoded){
        if(text.charCodeAt(0)===0xfeff)
          text=text.slice(1);
        seenDecoded=true;
      }
      processText(text);
    }catch(error){
      if(!(error instanceof Error))
        throw error;
      poisoned=true;
      throw error;
    }
    return frames.splice(0,frames.length);
  };

  const finish=()=>{
    if(poisoned||finished)
      throw new Error('decoder is closed');
    try{
      let text=utf8.decode(new Uint8Array(0),{stream:false});
      if(text.length>0){
        if(!seenDecoded&&text.charCodeAt(0)===0xfeff)
          text=text.slice(1);
        processText(text);
      }
      if(!terminated)
        throw new Error('stream did not end with a termination marker');
      if(line!=='')
        throw new Error('unterminated final line');
      if(frameData.length!==0||frameEvent!==null)
        throw new Error('pending frame fields at finish');
      finished=true;
    }catch(error){
      if(!(error instanceof Error))
        throw error;
      poisoned=true;
      throw error;
    }
    return [];
  };

  return {push,finish};
}

const B64_CHARS={};
for(const c of 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/')
  B64_CHARS[c]=c.charCodeAt(0);

// Canonical standard padded base64 exactly as Buffer.toString('base64')
// produces: alphabet only, length a multiple of 4, padding only at the end,
// and zero pad bits.
const isCanonicalBase64=str=>{
  if(!/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(str))
    return false;
  if(str.endsWith('==')){
    // The final group carries one byte: the low four bits of the second
    // data character are pad bits and must be zero.
    if(B64_CHARS[str.at(-3)]>=16)
      return false;
  }else if(str.endsWith('=')){
    // The low two bits of the second data character must be zero.
    if(B64_CHARS[str.at(-2)]>=64)
      return false;
  }
  return true;
};

const main=()=>{
  if(process.argv.length!==3)
    throw new Error('usage: stream-framer.js INPUT_JSON_FILE');
  const raw=fs.readFileSync(process.argv[2]);
  const input=JSON.parse(raw.toString('utf8'));
  if(typeof input!=='object'||input===null||Array.isArray(input))
    throw new Error('input must be a non-null non-array object');
  if(!Array.isArray(input.chunks))
    throw new Error('input.chunks must be an array');
  const decoder=createDecoder();
  const frames=[];
  for(const encoded of input.chunks){
    if(typeof encoded!=='string'||!isCanonicalBase64(encoded))
      throw new Error('chunk is not canonical base64');
    frames.push(...decoder.push(Buffer.from(encoded,'base64')));
  }
  frames.push(...decoder.finish());
  process.stdout.write(JSON.stringify({frames})+'\n');
};

if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){
  try{
    main();
  }catch(error){
    process.stderr.write((error&&error.message?error.message:String(error))+'\n');
    process.exitCode=2;
  }
}

